+void fragment() {
+	vec4 c = texture(TEXTURE, UV);
+	float g = dot(c.rgb, vec3(0.3, 0.59, 0.11));
+	vec3 col = vec3(g) * 0.55 + vec3(0.03, 0.025, 0.02);
